		T = minPlusMatMul(T, T)
		blocks >>= 1
	}

	// answer is cost to end with balance 0
	fmt.Println(vec[0])
}

func minPlusMatMul(A, B [][]int64) [][]int64 {
	n := len(A)
	C := make([][]int64, n)
	for i := 0; i < n; i++ {
		C[i] = make([]int64, n)
		for j := 0; j < n; j++ {
			C[i][j] = INF
		}
	}
	for i := 0; i < n; i++ {
		for k := 0; k < n; k++ {
			if A[i][k] == INF {
				continue
			}
			ak := A[i][k]
			rowB := B[k]
			rowC := C[i]
			for j := 0; j < n; j++ {
				if rowB[j] == INF {
					continue
				}
				val := ak + rowB[j]
				if val < rowC[j] {
					rowC[j] = val
				}
			}
		}
	}
	return C
}

func minPlusMatVec(A [][]int64, v []int64) []int64 {
	n := len(A)
	res := make([]int64, n)
	for i := 0; i < n; i++ {
		res[i] = INF
	}
	for i := 0; i < n; i++ {
		row := A[i]
		for j := 0; j < n; j++ {
			if row[j] == INF || v[i] == INF {
				continue
			}
			val := v[i] + row[j]
			if val < res[j] {
				res[j] = val
			}
		}
	}
	return res
}
