			nb := bal + 1
			if nb <= n {
				cost := dp[pos][bal] + a[pos]
				if cost < dp[pos+1][nb] {
					dp[pos+1][nb] = cost
				}
			}
			// close
			if bal > 0 {
				nb = bal - 1
				cost := dp[pos][bal] + b[pos]
				if cost < dp[pos+1][nb] {
					dp[pos+1][nb] = cost
				}
			}
		}
	}

	// transition matrix T[bal][bal'] = minimal cost to go from bal to bal' in one block
