	for i := range T {
		T[i] = make([]int64, n+1)
		for j := range T[i] {
			T[i][j] = INF
		}
	}
	for bal := 0; bal <= n; bal++ {
		for nb := 0; nb <= n; nb++ {
			if dp[n][nb] == INF {
				continue
			}
			// shift dp by starting balance bal
			// we need sequences where balance never negative and never exceeds n
			// This is ensured by original DP, so we can just add bal to all balances.
			// Starting from bal, ending at bal + (nb - 0) = bal + nb
			end := bal + nb
			if end < 0 || end > n {
